function makePlaceholderSync(objectType) {
  return async function syncPlaceholder() {
    return {
      status: 'skipped',
      created: 0,
      updated: 0,
      deleted: 0,
      warnings: [`${objectType} sync is not implemented yet.`],
      errors: [],
      summary: { placeholder: true }
    };
  };
}

const syncMetafields = makePlaceholderSync('metafields');
const syncMetaobjects = makePlaceholderSync('metaobjects');
const syncSellingPlans = makePlaceholderSync('selling plans');

module.exports = {
  syncMetafields,
  syncMetaobjects,
  syncSellingPlans
};
